class Solution {
public:
    int integerReplacement(int n) {
        long long val = n;
        int steps = 0;
        while (val > 1) {
            if (val % 2 == 0) {
                val /= 2;
            } else if (val == 3 || val % 4 == 1) {
                val--;
            } else {
                val++;
            }
            steps++;
        }
        return steps;
    }
};

