var integerReplacement = function(n) {
    let val = n;
    let steps = 0;
    while (val > 1) {
        if (val % 2 === 0) {
            val = Math.floor(val / 2);
        } else if (val === 3 || val % 4 === 1) {
            val--;
        } else {
            val++;
        }
        steps++;
    }
    return steps;
};
